+import type { ConfigurableTrait, Trait, TraitInstance } from '../trait/types';
+import type { World } from '../world/types';
+
+type Command =
+    | { type: 'spawn'; entity: Entity; traits: ConfigurableTrait[] }
+    | { type: 'destroy'; entity: Entity }
+    | { type: 'add'; entity: Entity; traits: ConfigurableTrait[] }
+    | { type: 'remove'; entity: Entity; traits: (Trait | RelationPair)[] }
+    | { type: 'addExclusive'; entity: Entity; pair: RelationPair };
+
+type Scope = { commands: Command[] };
+type Event = { instance: TraitInstance; entity: Entity; target?: Entity; before: boolean };
+
+export type DeferredState = {
+    scopes: Scope[];
+    virtualEntities: Set<Entity>;
+    flushing: boolean;
+    events: Map<string, Event>;
+};
+
+export type Deferred = {
+    spawn(...traits: ConfigurableTrait[]): Entity;
+    destroy(entity: Entity): void;
+    add(entity: Entity, ...traits: ConfigurableTrait[]): void;
+    remove(entity: Entity, ...traits: (Trait | RelationPair)[]): void;
+    addExclusive(entity: Entity, pair: RelationPair): void;
+    flush(): void;
+};
+
+export function createDeferredState(): DeferredState {
+    return { scopes: [{ commands: [] }], virtualEntities: new Set(), flushing: false, events: new Map() };
+}
+
+function state(world: World) {
+    return world[$internal].deferred!;
+}
+
+function current(world: World) {
+    const scopes = state(world).scopes;
+    return scopes[scopes.length - 1];
+}
+
+export function createDeferred(world: World): Deferred {
+    return {
+        spawn(...traits) {
+            const entity = createDeferredEntity(world);
+            state(world).virtualEntities.add(entity);
+            current(world).commands.push({ type: 'spawn', entity, traits });
+            return entity;
+        },
+        destroy(entity) {
+            current(world).commands.push({ type: 'destroy', entity });
+        },
+        add(entity, ...traits) {
+            current(world).commands.push({ type: 'add', entity, traits });
+        },
+        remove(entity, ...traits) {
+            current(world).commands.push({ type: 'remove', entity, traits });
+        },
+        addExclusive(entity, pair) {
+            if (!isRelationPair(pair)) throw new Error('Koota: addExclusive expects a relation pair.');
+            current(world).commands.push({ type: 'addExclusive', entity, pair });
+        },
+        flush() {
+            flushScope(world, current(world));
+        },
+    };
+}
+
+export function beginDeferredScope(world: World) {
+    state(world).scopes.push({ commands: [] });
+}
+
+export function endDeferredScope(world: World) {
+    const scope = current(world);
+    flushScope(world, scope);
+    state(world).scopes.pop();
+}
+
+export function flushPendingForEntity(world: World, entity: Entity) {
+    const deferred = state(world);
+    for (const scope of deferred.scopes) {
+        if (scope.commands.some((command) => command.entity === entity)) flushScope(world, scope);
+    }
+}
+
+export function hasDeferredCommands(world: World, entity: Entity) {
+    return state(world).scopes.some((scope) => scope.commands.some((command) => command.entity === entity));
+}
+
+/** A read-through view used by Entity#has. */
+export function hasAfterDeferred(world: World, entity: Entity, trait: Trait | RelationPair): boolean {
+    let value = isRelationPair(trait)
+        ? hasRelationPair(world, entity, trait)
+        : hasTrait(world, entity, trait);
+    let exists = state(world).virtualEntities.has(entity) || world.has(entity);
+    for (const scope of state(world).scopes) for (const command of scope.commands) {
+        if (command.entity !== entity) continue;
+        if (command.type === 'spawn') exists = true;
+        if (command.type === 'destroy') exists = false;
+        if (!exists) continue;
+        if (command.type === 'add') {
+            for (const config of command.traits) {
+                const candidate = Array.isArray(config) ? config[0] : config;
+                if (candidate === trait) value = true;
+                if (isRelationPair(trait) && isRelationPair(config) && samePair(config, trait)) value = true;
+            }
+        } else if (command.type === 'remove') {
+            for (const candidate of command.traits) {
+                if (candidate === trait) value = false;
+                if (isRelationPair(trait) && isRelationPair(candidate)) {
+                    if (candidate[$internal].relation === trait[$internal].relation &&
+                        (candidate[$internal].target === '*' || samePair(candidate, trait))) value = false;
+                }
+            }
+        } else if (command.type === 'addExclusive' && isRelationPair(trait)) {
+            const a = command.pair[$internal]; const b = trait[$internal];
+            if (a.relation === b.relation) value = a.target !== '*' && samePair(command.pair, trait);
+        }
+    }
+    return exists && value;
+}
+
+export function getAfterDeferred(world: World, entity: Entity, trait: Trait | RelationPair) {
+    if (!hasAfterDeferred(world, entity, trait)) return undefined;
+    let value = getTrait(world, entity, trait);
+    for (const scope of state(world).scopes) for (const command of scope.commands) {
+        if (command.entity !== entity || command.type !== 'add') continue;
+        for (const config of command.traits) {
+            if (isRelationPair(trait) && isRelationPair(config) && samePair(config, trait)) {
+                value = config[$internal].params;
+            } else if (!isRelationPair(trait) && Array.isArray(config) && config[0] === trait) {
+                value = config[1];
+            }
+        }
+    }
+    return value;
+}
+
+function samePair(a: RelationPair, b: RelationPair) {
+    return a[$internal].relation === b[$internal].relation && a[$internal].target === b[$internal].target;
+}
+
+function flushScope(world: World, scope: Scope) {
+    if (!scope.commands.length) return;
+    const deferred = state(world);
+    // A spawned entity that is destroyed before execution is deliberately never materialized.
+    const nullified = new Set<Entity>();
+    for (const command of scope.commands) if (command.type === 'destroy' && deferred.virtualEntities.has(command.entity)) nullified.add(command.entity);
+
+    const commands = scope.commands.splice(0);
+    deferred.flushing = true;
+    try {
+        for (const command of commands) {
+            if (nullified.has(command.entity)) {
+                deferred.virtualEntities.delete(command.entity);
+                continue;
+            }
+            if (command.type === 'spawn') {
+                if (deferred.virtualEntities.has(command.entity)) {
+                    materializeDeferredEntity(world, command.entity, ...command.traits);
+                    deferred.virtualEntities.delete(command.entity);
+                }
+                continue;
+            }
+            if (!world.has(command.entity)) continue;
+            if (command.type === 'destroy') {
+                if (command.entity === world[$internal].worldEntity) {
+                    throw new Error('Koota: The world entity cannot be destroyed through deferred commands.');
+                }
+                destroyEntity(world, command.entity);
+            } else if (command.type === 'add') {
+                // Unlike immediate add(), deferred adds carry the latest supplied value.
+                for (const config of command.traits) {
+                    addTrait(world, command.entity, config);
+                    const trait = Array.isArray(config) ? config[0] : config;
+                    if (Array.isArray(config) && hasTrait(world, command.entity, trait)) setTrait(world, command.entity, trait, config[1], false);
+                    if (isRelationPair(config) && hasRelationPair(world, command.entity, config) && config[$internal].params) setTrait(world, command.entity, config, config[$internal].params, false);
+                }
+            } else if (command.type === 'remove') {
+                removeTrait(world, command.entity, ...command.traits);
+            } else {
+                const relation = command.pair[$internal].relation;
+                removeTrait(world, command.entity, relation('*'));
+                if (command.pair[$internal].target !== '*') addTrait(world, command.entity, command.pair);
+            }
+        }
+    } finally {
+        deferred.flushing = false;
+        flushEvents(world);
+    }
+}
+
+export function notifyTraitAdd(world: World, instance: TraitInstance, entity: Entity, target?: Entity) {
+    notify(world, instance, entity, target, false, 'add');
+}
+export function notifyTraitRemove(world: World, instance: TraitInstance, entity: Entity, target?: Entity) {
+    notify(world, instance, entity, target, true, 'remove');
+}
+function notify(world: World, instance: TraitInstance, entity: Entity, target: Entity | undefined, before: boolean, type: 'add' | 'remove') {
+    const deferred = state(world);
+    if (!deferred.flushing) {
+        const subscriptions = type === 'add' ? instance.addSubscriptions : instance.removeSubscriptions;
+        for (const sub of subscriptions) sub(entity, target);
+        return;
+    }
+    const key = `${instance.trait.id}:${entity}:${target ?? ''}`;
+    if (!deferred.events.has(key)) deferred.events.set(key, { instance, entity, target, before });
+}
+function flushEvents(world: World) {
+    const deferred = state(world);
+    for (const event of deferred.events.values()) {
+        const relation = event.instance.trait[$internal].relation;
+        const after = relation && event.target !== undefined
+            ? getRelationTargets(world, relation, event.entity).includes(event.target)
+            : hasTrait(world, event.entity, event.instance.trait);
+        if (event.before === after) continue;
+        const subscriptions = after ? event.instance.addSubscriptions : event.instance.removeSubscriptions;
+        for (const sub of subscriptions) sub(event.entity, event.target);
+    }
+    deferred.events.clear();
+}
